function shopCoin(x,y,r,face){const h=face==='H';return `<g><circle cx="${x}" cy="${y}" r="${r}" fill="${h?SV.gold:'#c8cee2'}" stroke="${h?SV.goldD:'#8a94b0'}" stroke-width="${r>8?2:.7}"/><circle cx="${x}" cy="${y}" r="${r*.72}" fill="none" stroke="${h?'#fff3c4':'#eef0f8'}" stroke-width="${r>8?1.4:.5}"/>${r>6?svT(x,y+r*.36,face,{s:r,c:h?SV.goldD:'#6a7290'}):''}</g>`}
function shopBaskets(n,col,label,kind){let g='';for(let i=0;i<100;i++){const c=i%20,r=Math.floor(i/20),on=i<n;g+=`<g${on?` class="shop-hi" style="--d:${(i*.04).toFixed(2)}s"`:''}>${shopBasketIcon(16+c*14,26+r*16,1,on?col:'#d6dbec')}</g>`}
  return igFrame(300,118,`${g}${svT(150,114,label,{s:10.5,c:col===SV.twin?SV.twinD:SV.amberD})}`,label)}
// 100 runs of 8 orders from a fair Pantry: 43 with none steered, 38 with one, 15 with two, 3 with three, 1 with four (the binomial shares), shuffled.
function shopLuckRuns(){const counts=[].concat(Array(43).fill(0),Array(38).fill(1),Array(15).fill(2),Array(3).fill(3),[4]);let a=7;const rnd=()=>{a=(a*16807)%2147483647;return a/2147483647};
  for(let i=counts.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));[counts[i],counts[j]]=[counts[j],counts[i]]}
  return counts.map(k=>{const r=Array(8).fill(0);let placed=0;while(placed<k){const j=Math.floor(rnd()*8);if(!r[j]){r[j]=1;placed++}}return r})}

// The crate Pip and Jory push at the market
function shopCrateSVG(){return `<rect x="0" y="0" width="44" height="32" rx="3" fill="#c9a26b" stroke="#7a5426" stroke-width="2"/><path d="M2 10 H42 M2 22 H42" stroke="#a8824a" stroke-width="1.2"/>
  <text x="22" y="9" text-anchor="middle" font-size="5.6" font-family="Nunito" font-weight="800" fill="#5b3b16" textLength="26" lengthAdjust="spacingAndGlyphs">TOTALLY</text><text x="22" y="18" text-anchor="middle" font-size="5.6" font-family="Nunito" font-weight="800" fill="#5b3b16" textLength="36" lengthAdjust="spacingAndGlyphs">NORMAL COOLING</text><text x="22" y="27" text-anchor="middle" font-size="5.6" font-family="Nunito" font-weight="800" fill="#5b3b16" textLength="18" lengthAdjust="spacingAndGlyphs">FANS</text>`}
// The close-up card: the knot on a Kestrel robot and on a Pantry drone
